public class Student {
    private String name;
    private double gpa;
    private static int count = 0;       // shared by ALL students

    public Student() { this("Unknown", 0.0); }   // calls the other constructor

    public Student(String name, double gpa) {
        this.name = name;
        setGpa(gpa);                    // reuse the validation
        count++;
    }

    public String getName() { return name; }
    public double getGpa()  { return gpa; }

    public void setGpa(double gpa) {
        if (gpa >= 0 && gpa <= 4.0) this.gpa = gpa;
    }

    public static int getCount() { return count; }

    @Override
    public String toString() { return name + " (" + gpa + ")"; }

    public static void main(String[] args) {
        Student a = new Student("Amantle", 3.8);
        Student b = a;                  // SAME object, two names
        b.setGpa(2.0);
        System.out.println(a);          // Amantle (2.0)
        System.out.println(Student.getCount()); // 1
    }
}

