public class BankAccount {
  private double balance;
  public BankAccount(double balance) { this.balance = balance; }
  public void deposit(double a) { if (a > 0) balance += a; }
  public boolean withdraw(double a) {
    if (a > 0 && a <= balance) { balance -= a; return true; }
    return false;
  }
  public double getBalance() { return balance; }
  public static void main(String[] args) {
    BankAccount x = new BankAccount(100), y = new BankAccount(50);
    x.deposit(25);
    System.out.println(x.getBalance() + " " + y.getBalance()); // 125.0 50.0
  }
}
